window.MNEMIKA_MENTORPACK={"manifest": {"basePath": "assets/mentors/hires5", "characters": [{"id": "lena", "name": "Lena", "role": "Mathematik, Informatik und quantitative Aufgaben", "accent": "#6474FF", "poses": ["portrait", "01_greeting", "04_explaining", "05_thinking", "15_reflective", "11_laptop"]}, {"id": "sophie", "name": "Sophie", "role": "Biologie, Chemie, Physik, Gesundheit, Technik und Umwelt", "accent": "#15A07A", "poses": ["portrait", "01_greeting", "04_explaining", "05_thinking", "15_reflective", "11_laptop"]}, {"id": "maya", "name": "Maya", "role": "Deutsch, Fremdsprachen, Literatur, Gestaltung und Kommunikation", "accent": "#A855F7", "poses": ["portrait", "01_greeting", "02_thumbs_up", "04_explaining", "05_thinking", "11_laptop"]}, {"id": "dr-kofi", "name": "Dr. Kofi", "role": "Wirtschaft, Recht, Geschichte und Gesellschaft", "accent": "#7C3AED", "poses": ["portrait", "01_greeting", "02_thumbs_up", "03_pointing", "04_explaining", "09_explain_simple", "05_thinking", "17_mistake_safe", "11_laptop", "12_book"]}, {"id": "frau-keller", "name": "Frau Keller", "role": "Lernplanung, Projekte und Prüfungsvorbereitung", "accent": "#0F766E", "poses": ["portrait", "01_greeting", "02_thumbs_up", "03_pointing", "04_explaining", "06_idea", "09_explain_simple", "05_thinking", "15_reflective", "11_laptop", "12_book", "17_mistake_safe", "18_question"]}], "contextPose": {"home_recommendation": ["01_greeting", "portrait"], "chapter_intro": ["01_greeting", "portrait"], "important_concept": ["09_explain_simple", "04_explaining", "portrait"], "simpler_explanation": ["09_explain_simple", "04_explaining", "portrait"], "interim_check_before": ["18_question", "05_thinking", "portrait"], "answer_wrong": ["17_mistake_safe", "05_thinking", "portrait"], "worked_example": ["03_pointing", "11_laptop", "portrait"], "answer_correct": ["02_thumbs_up", "11_laptop", "portrait"], "exam_prep": ["11_laptop"], "formal_exam_result": ["11_laptop"], "uebung": ["11_laptop"], "test_start": ["18_question", "05_thinking", "portrait"], "wiederholen": ["12_book", "04_explaining", "portrait"], "pos1": ["04_explaining"], "pos2": ["11_laptop"], "pos3": ["04_explaining"], "pos4": ["11_laptop"], "pos5": ["04_explaining"], "pos6": ["11_laptop"], "pos7": ["04_explaining"], "pos8": ["11_laptop"]}, "rules": {"sameCharacterPerSession": true, "changePoseOnStateChange": true, "maxProminentPerViewport": 1, "maxLessonInterventions": 4, "formalExamBeforeSubmission": "forbidden", "messageFormula": ["specific observation", "important mental move", "concrete next action"]}}, "subject": {"math": "lena", "informatics": "lena", "biology": "sophie", "chemistry": "sophie", "physics": "sophie", "health": "sophie", "technology": "sophie", "field-fms-health": "sophie", "german": "maya", "english": "maya", "french": "maya", "italian": "maya", "spanish": "maya", "latin": "maya", "romansh": "maya", "languages": "maya", "greek": "maya", "russian": "maya", "arts": "maya", "communication": "maya", "field-fms-communication": "maya", "field-fms-design": "maya", "field-fms-music-theatre": "maya", "economics": "dr-kofi", "law": "dr-kofi", "accounting": "dr-kofi", "history": "dr-kofi", "geography": "dr-kofi", "social": "dr-kofi", "field-fms-social-work": "dr-kofi", "projects": "frau-keller", "orientation": "frau-keller", "sport": "frau-keller", "field-fms-pedagogy": "frau-keller"}, "placements": [{"slot": "home.today", "context": "home_recommendation", "size": "prominent", "frequency": "once per home view"}, {"slot": "lesson.intro", "context": "chapter_intro", "size": "prominent", "frequency": "once per lesson"}, {"slot": "lesson.critical-section", "context": "important_concept", "size": "compact", "frequency": "up to twice in a long lesson, only when the section contains a real misconception or difficult transition"}, {"slot": "lesson.interim-check", "context": "interim_check_before", "size": "compact", "frequency": "before selected checks, not before every question"}, {"slot": "practice.feedback", "context": "answer_correct or answer_wrong", "size": "compact", "frequency": "after submission only; keep the same character, change the pose"}, {"slot": "help.alternative-explanation", "context": "simpler_explanation", "size": "prominent", "frequency": "when requested"}, {"slot": "exam-prep.overview", "context": "exam_prep", "size": "compact", "frequency": "once per view"}, {"slot": "formal-exam.active", "context": "formal_exam_active", "size": "none", "frequency": "forbidden"}, {"slot": "formal-exam.result", "context": "formal_exam_result", "size": "compact", "frequency": "once after submission"}], "sizes": {"prominent": {"desktopImageCssPx": "168 to 220", "mobileImageCssPx": "112 to 144"}, "compact": {"desktopImageCssPx": "112 to 144", "mobileImageCssPx": "88 to 112"}}, "messages": {"lena": {"chapter_intro": {"h": "Kläre zuerst, was gesucht ist.", "m": "Notiere die gesuchte Grösse und die Beziehung zu den Angaben, bevor du Zahlen einsetzt. So erkennst du früh, ob dein Ansatz überhaupt zur Aufgabe passt."}, "important_concept": {"h": "0/0 ist kein Ergebnis.", "m": "Wenn Einsetzen 0/0 liefert, musst du den Term zuerst umformen. Kürzen, faktorisieren oder rationalisieren kommt vor der Grenzwertberechnung."}, "interim_check_before": {"h": "Schreib den Ansatz ohne Zahlen.", "m": "Eine symbolische Zeile zeigt schneller als jede Rechnung, ob du die richtige Formel gewählt hast."}, "answer_wrong": {"h": "Der erste Bruch liegt beim Umformen.", "m": "Geh eine Zeile zurück. Prüfe, ob du auf beiden Seiten dieselbe Operation ausgeführt und das Vorzeichen erhalten hast."}, "answer_correct": {"h": "Der Ansatz trägt.", "m": "Prüfe noch Einheit, Vorzeichen und Grössenordnung. Dann ist aus einem richtigen Resultat eine belastbare Lösung geworden."}, "worked_example": {"h": "Rechne den Weg, nicht das Ergebnis.", "m": "Schreibe jede Umformung als eigene Zeile und markiere, welche Regel du anwendest. In der Prüfung geben genau diese Zwischenschritte die Punkte."}, "simpler_explanation": {"h": "Nimm zuerst konkrete Zahlen.", "m": "Setze für die Variablen kleine Werte ein und rechne den Fall von Hand. Danach ersetzt du die Zahlen wieder durch Buchstaben und siehst, was die Formel beschreibt."}, "home_recommendation": {"h": "Beginne mit dem Ansatz von gestern.", "m": "Nimm die Aufgabe, bei der du zuletzt stecken geblieben bist, und schreibe nur den Ansatz neu. Erst wenn der steht, rechnest du weiter."}, "exam_prep": {"h": "Übe unter Zeit, nicht nur auf Richtigkeit.", "m": "Nimm eine ganze Aufgabe und setze dir die Prüfungszeit. Danach prüfst du, wo du Zeit verloren hast, und wiederholst genau diesen Aufgabentyp."}, "formal_exam_result": {"h": "Lies zuerst die Aufgaben mit Methodefehlern.", "m": "Trenne Rechenfehler von Ansatzfehlern. Ansatzfehler wiederholst du am selben Tag, Rechenfehler übst du mit kurzen Serien."}, "uebung": {"h": "Rechne heute in Serien.", "m": "Nimm fünf Aufgaben desselben Typs hintereinander. Erst dann wechselst du das Thema; so festigt sich der Ansatz statt nur das Ergebnis."}, "test_start": {"h": "Lies die Angabe zweimal.", "m": "Markiere die gesuchte Grösse, bevor du rechnest. Die meisten Punkte gehen verloren, weil eine andere Grösse berechnet wurde als verlangt."}, "wiederholen": {"h": "Beginne mit dem Ansatz, nicht mit der Formel.", "m": "Sag zu jeder fälligen Aufgabe zuerst, welcher Weg passt. Die Rechnung folgt danach fast von allein."}, "pos1": {"h": "Lies die Angabe, bevor du rechnest.", "m": "Streiche an, welche Grösse gesucht ist und welche gegeben sind. Die meisten Punkte gehen verloren, weil etwas anderes berechnet wurde als verlangt."}, "pos2": {"h": "Ein Ansatz ist eine Gleichung, kein Ergebnis.", "m": "Schreibe die Beziehung zwischen den Grössen auf, bevor du Zahlen einsetzt. Erst dann siehst du, ob der Weg überhaupt zum Ziel führt."}, "pos3": {"h": "Prüfe die Bedingung, nicht nur die Formel.", "m": "Jede Umformung gilt unter einer Voraussetzung. Notiere sie am Rand; in der Prüfung zählt sie als eigener Schritt."}, "pos4": {"h": "Rechne das Beispiel selbst nach.", "m": "Deck die Lösung ab und rechne mit. Erst wenn dein Weg ohne Vorlage steht, hast du ihn verstanden."}, "pos5": {"h": "Die Einheit verrät den Fehler.", "m": "Stimmt die Einheit nicht, stimmt die Formel nicht. Diese Kontrolle kostet zehn Sekunden und rettet ganze Aufgaben."}, "pos6": {"h": "Übertrage auf eine andere Zahl.", "m": "Ersetze eine Angabe durch eine andere und rechne erneut. Was dann noch klappt, sitzt wirklich."}, "pos7": {"h": "Halte den Weg schriftlich fest.", "m": "Schreibe jeden Schritt als eigene Zeile. In der schriftlichen Prüfung werden Zwischenschritte einzeln bewertet."}, "pos8": {"h": "Fasse in einem Satz zusammen.", "m": "Sag in einem Satz, was dieses Verfahren leistet. Was du frei erklären kannst, brauchst du nicht auswendig zu lernen."}}, "sophie": {"chapter_intro": {"h": "Ordne zuerst die biologische Ebene.", "m": "Frag dich, ob die Aufgabe ein Molekül, eine Zelle, ein Organ oder eine Population beschreibt. Erst dann lassen sich Struktur, Prozess und Funktion sauber verbinden."}, "important_concept": {"h": "Mitose und Meiose verfolgen verschiedene Ziele.", "m": "Vergleiche nicht nur die Zahl der Teilungen. Entscheidend sind Zweck, Chromosomensatz und genetische Vielfalt der entstehenden Zellen."}, "worked_example": {"h": "Trenne Beobachtung und Erklärung.", "m": "Beschreibe zuerst, was die Daten zeigen. Danach erklärst du den Befund mit dem passenden Modell. So bleibt deine Schlussfolgerung überprüfbar."}, "answer_wrong": {"h": "Struktur und Funktion sind vertauscht.", "m": "Nenne zuerst, was vorhanden ist. Erkläre danach, was dort geschieht und welche Aufgabe dieser Vorgang erfüllt."}, "answer_correct": {"h": "Die Prozesskette stimmt.", "m": "Deine Erklärung zeigt Ausgangslage, Veränderung und Folge. Ergänze bei Bedarf noch die Bedingung, unter der der Prozess abläuft."}, "interim_check_before": {"h": "Nenne Ebene und Bedingung.", "m": "Sag dir vor dem Antworten, auf welcher Ebene die Frage liegt und welche Bedingung gelten muss. Das verhindert die häufigste Verwechslung."}, "simpler_explanation": {"h": "Erzähl den Vorgang als Abfolge.", "m": "Beschreibe Ausgangslage, Veränderung und Ergebnis in drei Sätzen. Fachbegriffe setzt du erst ein, wenn die Abfolge stimmt."}, "home_recommendation": {"h": "Nimm ein Kapitel mit Prozess.", "m": "Wähle heute einen Vorgang mit klaren Schritten und zeichne ihn ohne Vorlage auf. Was du zeichnen kannst, kannst du auch erklären."}, "exam_prep": {"h": "Übe das Beschreiben von Daten.", "m": "Nimm eine Grafik aus dem Kapitel, beschreibe zuerst nur die Beobachtung und erkläre danach mit dem Modell. Genau diese Trennung wird bewertet."}, "formal_exam_result": {"h": "Prüfe, wo die Erklärung abbricht.", "m": "Suche die Antwort, in der du beschrieben, aber nicht erklärt hast. Ergänze dort das Modell und den Grund."}, "uebung": {"h": "Übe das Erklären mit.", "m": "Sprich zu jeder Aufgabe laut aus, welcher Vorgang abläuft. Wer den Vorgang erzählen kann, besteht auch die Transferaufgabe."}, "test_start": {"h": "Trenne Beobachtung und Erklärung.", "m": "Schreibe zuerst, was messbar ist, und danach die Deutung mit dem Modell. Beide Teile werden getrennt bewertet."}, "wiederholen": {"h": "Frisch die Bedingungen auf.", "m": "Bei jedem Vorgang gilt eine Bedingung, etwa Temperatur oder Konzentration. Genau diese wird in Wiederholungen gern vergessen."}, "pos1": {"h": "Bestimme zuerst die Ebene.", "m": "Molekül, Zelle, Organ oder Population: erst wenn die Ebene klar ist, passen Struktur, Vorgang und Funktion zusammen."}, "pos2": {"h": "Beschreibe, bevor du erklärst.", "m": "Halte fest, was zu sehen oder zu messen ist. Die Erklärung mit dem Modell folgt im zweiten Schritt und wird getrennt bewertet."}, "pos3": {"h": "Nenne die Bedingung des Vorgangs.", "m": "Temperatur, pH-Wert oder Konzentration entscheiden, ob ein Vorgang abläuft. Ohne Bedingung bleibt die Erklärung unvollständig."}, "pos4": {"h": "Verfolge den Stoff durch den Vorgang.", "m": "Frag bei jedem Schritt, was hineingeht und was herauskommt. So merkst du sofort, wenn ein Zwischenprodukt fehlt."}, "pos5": {"h": "Bau und Funktion gehören zusammen.", "m": "Erkläre die Leistung aus dem Bau, nicht umgekehrt. Genau diese Richtung verlangen Prüfungsaufgaben."}, "pos6": {"h": "Zeichne den Ablauf ohne Vorlage.", "m": "Was du aufzeichnen kannst, kannst du auch erklären. Vergleiche danach mit der Darstellung im Text."}, "pos7": {"h": "Unterscheide Ursache und Begleitumstand.", "m": "Nicht alles, was gleichzeitig geschieht, ist die Ursache. Prüfe, was sich ändern müsste, damit der Vorgang ausbleibt."}, "pos8": {"h": "Nenne Zweck, Ort und Ergebnis.", "m": "Diese drei Angaben verlangen Prüfungsaufgaben fast immer. Prüfe am Schluss, ob alle drei in deiner Antwort stehen."}}, "maya": {"chapter_intro": {"h": "Beginne mit der Aussage, nicht mit dem Stilmittel.", "m": "Formuliere zuerst, was der Absatz sagt. Erst danach suchst du den sprachlichen Befund, der diese Aussage oder Wirkung trägt."}, "important_concept": {"h": "Ein Beleg braucht eine Erklärung.", "m": "Zitiere oder paraphrasiere knapp. Zeige dann, weshalb genau diese Stelle deine Deutung stützt."}, "worked_example": {"h": "Ein Absatz, ein Gedanke.", "m": "Setze eine klare Behauptung an den Anfang. Danach folgen Beleg, Erklärung und ein Satz, der den Gedanken zur Leitfrage zurückführt."}, "answer_wrong": {"h": "Du nennst den Beleg, aber nicht seine Wirkung.", "m": "Ergänze einen Satz dazu, was die Formulierung beim Leser auslöst oder zur Aussage des Textes beiträgt."}, "answer_correct": {"h": "Die Antwort ist belegt.", "m": "Dein Text verbindet Aussage und Fundstelle. Prüfe jetzt noch, ob die Wortwahl zur verlangten Textsorte und zum Adressaten passt."}, "interim_check_before": {"h": "Formuliere die Aussage zuerst.", "m": "Sag in einem Satz, worum es in der Stelle geht. Erst danach suchst du den Beleg, der zu dieser Aussage passt."}, "home_recommendation": {"h": "Zehn Minuten am Text.", "m": "Lies einen Abschnitt und schreibe dazu zwei Sätze: was er sagt und wie er es sagt. Mehr braucht es für heute nicht."}, "exam_prep": {"h": "Schreib eine Antwort vollständig.", "m": "Statt vieler Stichworte formulierst du eine Antwort mit Behauptung, Beleg und Erklärung. Das ist die Form, die in der Prüfung zählt."}, "simpler_explanation": {"h": "Übersetze den Satz in Alltagssprache.", "m": "Sag den Inhalt zuerst mit eigenen Worten. Danach setzt du die Fachbegriffe wieder ein und prüfst, ob die Aussage gleich bleibt."}, "formal_exam_result": {"h": "Zähle deine Belege.", "m": "Geh deine Antworten durch und markiere jede Deutung ohne Textstelle. Genau dort verlierst du regelmässig Punkte."}, "uebung": {"h": "Übe mit Belegstellen.", "m": "Zu jeder Antwort gehört die Zeile, aus der sie folgt. Lesekompetenz zeigt sich am Beleg, nicht an der Meinung."}, "test_start": {"h": "Kläre zuerst die Aufgabenstellung.", "m": "Unterstreiche den Operator, etwa nenne, erkläre oder beurteile. Er bestimmt, wie ausführlich die Antwort sein muss."}, "wiederholen": {"h": "Wiederhole Wörter in Sätzen.", "m": "Nimm zu jedem Wort einen ganzen Satz aus dem Kapitel. Der Satz speichert die Verwendung gleich mit."}, "pos1": {"h": "Erfasse die Hauptaussage zuerst.", "m": "Formuliere in einem Satz und in eigenen Worten, worum es geht. Danach erst gehst du ins Detail."}, "pos2": {"h": "Belege mit einer Zeile aus dem Text.", "m": "Lesekompetenz zeigt sich am Beleg, nicht an der Meinung. Nenne die Stelle, aus der deine Antwort folgt."}, "pos3": {"h": "Erkläre die Wirkung der Wortwahl.", "m": "Ein Zitat allein zählt nicht. Sag, was die Formulierung bei der lesenden Person auslöst."}, "pos4": {"h": "Lerne Wörter im Satz.", "m": "Der Satz speichert die Verwendung mit. Eine Wortliste ohne Zusammenhang verschwindet bis zur Prüfung."}, "pos5": {"h": "Achte auf die Zeitform.", "m": "Sie trägt in Antworten oft mehr Bedeutung als das einzelne Wort. Prüfe sie vor der Abgabe."}, "pos6": {"h": "Sprich die Stelle laut.", "m": "Aussprache und Betonung festigen die Schreibung. Zwei Minuten laut lesen ersetzt zehn Minuten stilles Wiederholen."}, "pos7": {"h": "Vergleiche mit deiner ersten Sprache.", "m": "Wo die Sprachen übereinstimmen, geht es schnell. Wo sie abweichen, entstehen die typischen Fehler."}, "pos8": {"h": "Antworte in ganzen Sätzen.", "m": "Stichworte wirken unfertig und verlieren Punkte, auch wenn der Inhalt stimmt."}}, "dr-kofi": {"chapter_intro": {"h": "Trenne Tatsache, Modell und Urteil.", "m": "Halte zuerst fest, was gegeben ist. Wähle dann das passende wirtschaftliche oder rechtliche Modell. Das Urteil kommt erst am Schluss."}, "important_concept": {"h": "Eine Preisänderung verschiebt nicht automatisch die Kurve.", "m": "Ein anderer Preis führt zu einer Bewegung auf der bestehenden Kurve. Einkommen, Kosten oder Erwartungen verschieben die ganze Kurve."}, "worked_example": {"h": "Prüfe jedes Tatbestandsmerkmal einzeln.", "m": "Formuliere die Rechtsfrage, nenne die Regel und ordne jeder Voraussetzung eine konkrete Tatsache aus dem Fall zu."}, "answer_wrong": {"h": "Der Sprung zum Ergebnis ist zu gross.", "m": "Zeige die fehlende Wirkungskette oder Subsumtion. Ein richtig klingendes Ergebnis genügt ohne Begründung nicht."}, "answer_correct": {"h": "Die Wirkungskette ist schlüssig.", "m": "Nenne noch, welche Annahme dafür gelten muss und wer von der Veränderung profitiert oder belastet wird."}, "interim_check_before": {"h": "Nenne die Regel vor dem Fall.", "m": "Sag zuerst, welche Norm oder welches Modell gilt. Dann ordnest du die Angaben aus der Aufgabe zu."}, "simpler_explanation": {"h": "Erzähl den Fall als Geschichte.", "m": "Beschreibe, wer was tut und was daraus folgt. Danach setzt du die Fachbegriffe ein und prüfst, ob die Kette noch stimmt."}, "home_recommendation": {"h": "Ein Fall statt vieler Begriffe.", "m": "Nimm heute einen vollständigen Fall und arbeite ihn von der Frage bis zum Ergebnis durch. Das trägt mehr als eine Begriffsliste."}, "exam_prep": {"h": "Übe die Gliederung, nicht das Auswendiglernen.", "m": "Schreibe zu drei Aufgaben nur die Gliederung aus Frage, Regel, Zuordnung und Ergebnis. Die Struktur gibt die Punkte."}, "formal_exam_result": {"h": "Suche die fehlende Zuordnung.", "m": "Prüfe, wo du eine Regel genannt, aber nicht auf den Sachverhalt angewendet hast. Dort fehlt die Subsumtion."}, "uebung": {"h": "Übe in Ursache und Folge.", "m": "Formuliere zu jeder Aufgabe einen Satz mit weil und deshalb. Prüfungsaufgaben fragen fast immer nach dem Zusammenhang, nicht nach dem Datum."}, "test_start": {"h": "Nenne zuerst das Kriterium.", "m": "Wer beurteilt, sagt vorher, woran gemessen wird. Ohne Kriterium bleibt das Urteil eine Behauptung und kostet Punkte."}, "wiederholen": {"h": "Ordne Ereignisse in eine Linie.", "m": "Lege zu jedem wiederholten Thema drei Eckdaten in die richtige Reihenfolge. Die Linie hält den Stoff zusammen."}, "pos1": {"h": "Ordne die Sache zeitlich ein.", "m": "Halte fest, wann etwas geschah und was davor lag. Ohne Einordnung bleibt jede Deutung beliebig."}, "pos2": {"h": "Trenne Anlass und Ursache.", "m": "Der Anlass löst aus, die Ursache wirkt lange davor. Prüfungsaufgaben fragen nach der Ursache."}, "pos3": {"h": "Nenne die Perspektive der Quelle.", "m": "Wer spricht, verändert, was gesagt wird. Verfasser, Adressat und Absicht gehören vor die inhaltliche Auswertung."}, "pos4": {"h": "Beschreibe das Muster, dann die Ursache.", "m": "Bei Karten und Daten zuerst benennen, was zu sehen ist. Die Erklärung folgt getrennt."}, "pos5": {"h": "Sag dein Kriterium vor dem Urteil.", "m": "Woran misst du? Dauerhaftigkeit, Reichweite oder Kosten. Ohne Kriterium ist das Urteil eine Behauptung."}, "pos6": {"h": "Verbinde Ursache, Verlauf und Folge.", "m": "Diese Gliederung trägt die meisten Antworten und verhindert reines Aufzählen."}, "pos7": {"h": "Prüfe, wer profitiert und wer belastet wird.", "m": "Diese Frage öffnet fast jede wirtschaftliche und politische Aufgabe."}, "pos8": {"h": "Fasse in drei Eckdaten zusammen.", "m": "Drei Punkte in der richtigen Reihenfolge halten das Thema zusammen und lassen sich im Gespräch abrufen."}}, "frau-keller": {"home_recommendation": {"h": "Mach den nächsten Schritt klein genug.", "m": "Beginne mit einer fälligen Wiederholung und fünf Aufgaben aus deinem schwächsten Kapitel. Danach entscheidest du neu."}, "chapter_intro": {"h": "Du musst nicht alles auf einmal behalten.", "m": "Arbeite Abschnitt für Abschnitt. Nach jedem Teil schliesst du den Text und erklärst den Zusammenhang in eigenen Worten."}, "interim_check_before": {"h": "Jetzt ohne Spickzettel.", "m": "Formuliere den Kern in zwei Sätzen. Wenn eine Verbindung fehlt, gehst du genau zu diesem Abschnitt zurück."}, "answer_wrong": {"h": "Du brauchst nicht die ganze Lektion neu.", "m": "Finde den ersten Begriff oder Schritt, an dem deine Begründung abbricht. Wiederhole nur diesen Teil und versuche es nochmals."}, "exam_prep": {"h": "Plane rückwärts vom Prüfungstag.", "m": "Teile den Stoff in Wiederholen, Anwenden und Prüfen. Reserviere die letzten Tage für ganze Aufgaben unter Zeitdruck, nicht für neuen Stoff."}, "important_concept": {"h": "Halte hier kurz an.", "m": "Dieser Abschnitt trägt den Rest des Kapitels. Schliess den Text und erklär den Zusammenhang laut, bevor du weiterliest."}, "worked_example": {"h": "Erst mitlesen, dann nachrechnen.", "m": "Geh das Beispiel einmal lesend durch und decke es danach ab. Beim zweiten Durchgang schreibst du die Schritte selbst."}, "simpler_explanation": {"h": "Zerleg den Abschnitt in drei Teile.", "m": "Notiere Begriff, Bedingung und Anwendung getrennt. Fehlt dir einer der drei, weisst du genau, wo du nachlesen musst."}, "answer_correct": {"h": "Der Schritt sitzt.", "m": "Notiere in einem Satz, woran du die richtige Möglichkeit erkannt hast. Diese Notiz hilft dir bei der nächsten Wiederholung."}, "formal_exam_result": {"h": "Plane die nächsten drei Tage.", "m": "Nimm die zwei schwächsten Themen und verteile sie auf drei kurze Einheiten. Neuen Stoff nimmst du erst danach dazu."}, "uebung": {"h": "Schreib heute kurz und vollständig.", "m": "Formuliere zu jeder Aufgabe einen vollständigen Satz mit Behauptung und Beleg statt Stichworten. Das ist die Form, die in der Prüfung zählt."}, "test_start": {"h": "Plane zwei Minuten, bevor du schreibst.", "m": "Notiere These und drei Argumente als Stichworte. Der Text wird danach schneller und der rote Faden bleibt sichtbar."}, "wiederholen": {"h": "Wiederhole an Textstellen, nicht an Begriffen.", "m": "Nimm zu jedem Begriff eine Stelle aus deiner Lektüre. Begriffe ohne Beleg verschwinden bis zur Prüfung wieder."}, "pos1": {"h": "Kläre zuerst die Aufgabe.", "m": "Unterstreiche den Operator: nennen, erklären oder beurteilen. Er bestimmt, wie ausführlich deine Antwort sein muss."}, "pos2": {"h": "Eine Behauptung braucht einen Beleg.", "m": "Setze zu jeder Aussage die Stelle, aus der sie folgt. Ohne Beleg bleibt es eine Meinung und zählt nicht."}, "pos3": {"h": "Trenne Inhalt und Wirkung.", "m": "Was steht da, und was löst es aus? Beide Teile werden getrennt bewertet und dürfen nicht vermischt werden."}, "pos4": {"h": "Ein Absatz, ein Gedanke.", "m": "Beginne mit der Behauptung, dann Beleg, dann Erklärung. Dieser Aufbau trägt jeden Prüfungstext."}, "pos5": {"h": "Nimm die Gegenposition ernst.", "m": "Stelle sie in ihrer stärksten Form dar. Nur so zeigt sich, dass deine These auch unter Widerspruch hält."}, "pos6": {"h": "Schreib den Schluss ohne neue Gedanken.", "m": "Das Fazit folgt aus dem Gesagten. Neue Argumente am Schluss wirken unfertig und kosten Punkte."}, "pos7": {"h": "Lies deinen Text laut.", "m": "Was du beim Lautlesen stolpernd liest, liest auch die korrigierende Person stolpernd."}, "pos8": {"h": "Prüfe Bezug und Zeitform.", "m": "Gerade bei langen Sätzen geraten Bezüge durcheinander. Diese Kontrolle bringt im Schnitt mehr als jede Umformulierung."}}}, "banned": ["Du schaffst das.", "Weiter so!", "Super gemacht!", "Das ist wichtig.", "Hier liegt dein Hebel.", "Du bist ein Genie."]};

